import addFormats from 'ajv-formats'
import fs from 'node:fs'
import path from 'node:path'
import YAML from 'yaml'

const schema = JSON.parse(
  fs.readFileSync('/workspace/repo/src/schemas/json/bamboo-spec.json', 'utf8'),
)

const ajv = new AjvDraft04({
  strictTypes: false,
  strictTuples: false,
  allowMatchingProperties: true,
  allErrors: false,
})
addFormats.default(ajv)
const validate = ajv.compile(schema)

// 1. Existing fixtures
const fixDir = '/workspace/repo/src/test/bamboo-spec'
const fixtures = fs.readdirSync(fixDir)
let fail = 0
for (const f of fixtures) {
  const raw = fs.readFileSync(path.join(fixDir, f), 'utf8')
  const doc = f.endsWith('.json') ? JSON.parse(raw) : YAML.parse(raw)
  const ok = validate(doc)
  if (!ok) {
    fail++
    console.log('FIXTURE FAIL:', f)
    console.log(JSON.stringify(validate.errors, null, 2))
  } else {
    console.log('fixture ok:', f)
  }
}

// 2. Constructed docs covering requirements
const cases = JSON.parse(fs.readFileSync('/tmp/cases.json', 'utf8'))
for (const [name, doc] of Object.entries(cases)) {
  const ok = validate(doc)
  if (!ok) {
    fail++
    console.log('CASE FAIL:', name)
    console.log(JSON.stringify(validate.errors, null, 2))
  } else {
    console.log('case ok:', name)
  }
}

console.log('\nTOTAL FAILURES:', fail)
